    for c in pod['spec']['containers']:
        env = c.get('env', [])
        envFrom = c.get('envFrom', [])
        if env or envFrom:
            print(f'{name} / {c[\"name\"]}:')
            for e in env:
                print(f'  {e[\"name\"]}={e.get(\"value\", \"<ref>\")}')
            for ef in envFrom:
                print(f'  from: {ef}')
" 2>&1 | head -80

